module tb;
  localparam WIDTH = 8;
  localparam DEPTH = 4;
  reg clk = 0;
  reg rst_n = 0;
  reg winc = 0;
  reg rinc = 0;
  reg [WIDTH-1:0] wdata = 0;
  wire wfull, rempty;
  wire [WIDTH-1:0] rdata;

  TopModule #(.WIDTH(WIDTH), .DEPTH(DEPTH)) dut (
    .clk(clk), .rst_n(rst_n), .winc(winc), .rinc(rinc), .wdata(wdata),
    .wfull(wfull), .rempty(rempty), .rdata(rdata)
  );

  always #5 clk = ~clk;

  task do_write(input [WIDTH-1:0] d);
    begin
      @(negedge clk); winc = 1; wdata = d;
      @(negedge clk); winc = 0;
    end
  endtask

  task do_read;
    begin
      @(negedge clk); rinc = 1;
      @(negedge clk); rinc = 0;
    end
  endtask

  integer i;
  initial begin
    "'$display("start");
    repeat (2) @(negedge clk);
    rst_n = 1;

    for (i = 0; i < DEPTH; i = i + 1) do_write(i+8'"'h10);
    for (i = 0; i < DEPTH; i = i + 1) begin
      do_read();
      @(posedge clk); #1;
      "'$display("read0[%0d] rdata=%0h rempty=%0b wfull=%0b waddr=%0d raddr=%0d", i, rdata, rempty, wfull, dut.waddr, dut.raddr);
    end

    for (i = 0; i < DEPTH; i = i + 1) do_write(i+8'"'h20);
    for (i = 0; i < DEPTH; i = i + 1) begin
      do_read();
      @(posedge clk); #1;
      "'$display("read1[%0d] rdata=%0h rempty=%0b wfull=%0b waddr=%0d raddr=%0d", i, rdata, rempty, wfull, dut.waddr, dut.raddr);
    end

    $finish;
  end
endmodule
EOF
